from collections import deque
def comps(g, bg, color=None):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and not seen[i][j] and (color is None or g[i][j]==color):
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                col=g[i][j]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                out.append((col,cells))
    return out

