def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))
def rot(cells):
    return tuple(sorted((c,-r) for r,c in cells))
def all_rots(sig):
    s=sig
    out=set()
    for _ in range(4):
        out.add(s); out.add(tuple(sorted((-r,c) for r,c in s)))
        s=rot(s)
    return out

